def router_training_losses(self, model, x_start, t, model_kwargs=None, noise=None, dropout_prob=0.1):
    assert model_kwargs is not None
    label_for_dropout = th.rand(x_start.shape[0], device=x_start.device) < dropout_prob
    model_kwargs['label_for_dropout'] = label_for_dropout
    with th.no_grad():
        noise = th.randn_like(x_start)
        x_t = self.q_sample(x_start, t, noise=noise)
        x_next = self.ddim_sample(
            model, x_t, t, 
            clip_denoised=False, denoised_fn=None, cond_fn=None, 
            model_kwargs=model_kwargs, eta=0.0
        )['sample']
    next_t = t - 1
    map_tensor = th.tensor(self.timestep_map, device=next_t.device, dtype=next_t.dtype)
    new_ts = map_tensor[next_t]
    model_kwargs['fix_reuse_feature'] = True
    ori_model_output = model(x_next, new_ts, **model_kwargs)
    model_kwargs['activate_router'] = True
    pred_model_output, l1_loss = model(x_next, new_ts, **model_kwargs)
    terms = {}
    terms['l1_loss'] = l1_loss
    terms['mse'] = mean_flat((ori_model_output - pred_model_output) ** 2)
    return terms

# From DiT/models/router_models.py
def modulate(x, shift, scale):
    return x * (1 + scale.unsqueeze(1)) + shift.unsqueeze(1)

class STE(torch.autograd.Function):
     @staticmethod
     def forward(ctx, i, thres=0.5):
         return (i>thres).float()

     @staticmethod
     def backward(ctx, grad_output):
         return grad_output, None

class Router(nn.Module):
    def __init__(self, num_choises):
        super().__init__()
        self.num_choises = num_choises
        self.prob = torch.nn.Parameter(torch.randn(num_choises), requires_grad=True)
        self.activation = torch.nn.Sigmoid()

    def forward(self, x=None):
        return self.activation(self.prob)

class DiTBlock(nn.Module):
    def forward(self, x, c, reuse_att=None, reuse_mlp=None,
                reuse_att_weight=0, reuse_mlp_weight=0):
        shift_msa, scale_msa, gate_msa, shift_mlp, scale_mlp, gate_mlp = self.adaLN_modulation(c).chunk(6, dim=1)
        att_out = self.attn(modulate(self.norm1(x), shift_msa, scale_msa))
        if reuse_att is not None:
            att_out = reuse_att * reuse_att_weight + att_out * (1 - reuse_att_weight)
        x = x + gate_msa.unsqueeze(1) * att_out

        mlp_out = self.mlp(modulate(self.norm2(x), shift_mlp, scale_mlp))
        if reuse_mlp is not None:
            mlp_out = reuse_mlp * reuse_mlp_weight + mlp_out * (1 - reuse_mlp_weight)
        x = x + gate_mlp.unsqueeze(1) * mlp_out
        return x, (att_out, mlp_out)

class DiT(nn.Module):
    def reset(self):
        self.reuse_feature = [None] * self.depth

    def add_router(self, num_steps, timestep_map):
        self.routers = torch.nn.ModuleList([
            Router(2*self.depth) for _ in range(num_steps)
        ])
        self.timestep_map = {timestep: i for i, timestep in enumerate(timestep_map)}

    def forward(self, x, t, y, thres=None, activate_router=False, fix_reuse_feature=False, label_for_dropout=None):
        x = self.x_embedder(x) + self.pos_embed
        timestep = t[0].item()
        t = self.t_embedder(t)
        y = self.y_embedder(y, self.training, force_drop_ids=label_for_dropout)
        c = t + y       

        if activate_router :
            router_idx = self.timestep_map[timestep]
            scores = self.routers[router_idx]()
            if thres is None:
                weights = scores
            else:
                weights = STE.apply(scores, thres)
            router_l1_loss = scores.sum()
        else:
            router_l1_loss = None

        for i, block in enumerate(self.blocks):
            att, mlp = None, None
            reuse_att_weight, reuse_mlp_weight = 0, 0
            if self.reuse_feature[i] is not None and activate_router:
                att = self.reuse_feature[i][0]
                reuse_att_weight = 1 - weights[i*2]

            if self.reuse_feature[i] is not None and activate_router:
                mlp = self.reuse_feature[i][1]
                reuse_mlp_weight = 1 - weights[i*2+1]

            x, reuse_feature = block(x, c, reuse_att=att, reuse_mlp=mlp, 
                                     reuse_att_weight=reuse_att_weight,
                                     reuse_mlp_weight=reuse_mlp_weight)

            if not fix_reuse_feature:
                self.reuse_feature[i] = reuse_feature

        x = self.final_layer(x, c)
        x = self.unpatchify(x)

        if activate_router:
            return x, router_l1_loss
        else:
            return x

# From DiT/models/dynamic_models.py (inference implementation)
class DiT_Inference(nn.Module):
    def reset(self, start_timestep=20):
        self.cur_timestep = start_timestep-1
        self.reuse_feature = [None] * self.depth

    def load_ranking(self, path, num_steps, timestep_map, thres):
        self.rank = [None] * num_steps
        from models.router_models import Router, STE
        ckpt = torch.load(path, map_location='cpu')['routers']
        routers = torch.nn.ModuleList([
            Router(2*self.depth) for _ in range(num_steps)
        ])
        routers.load_state_dict(ckpt)
        self.timestep_map =  {timestep: i for i, timestep in enumerate(timestep_map)}

        for idx, router in enumerate(routers):
            if idx % 2 == 0:
                self.rank[idx] = STE.apply(router(), thres).nonzero().squeeze(0)

    def forward(self, x, t, y):
        x = self.x_embedder(x) + self.pos_embed
        timestep = t[0].item()
        router_idx = self.timestep_map[timestep]

        t = self.t_embedder(t)
        y = self.y_embedder(y, self.training)
        c = t + y

        if self.cur_timestep % 2 == 1:
            self.reuse_feature = [None] * len(self.reuse_feature)

        for i, block in enumerate(self.blocks):
            att, mlp = None, None

            if self.reuse_feature[i] is not None and 2*i not in self.rank[router_idx] :
                att = self.reuse_feature[i][0]

            if self.reuse_feature[i] is not None and 2*i+1 not in self.rank[router_idx] :
                mlp = self.reuse_feature[i][1]

            x, reuse_feature = block(x, c, reuse_att=att, reuse_mlp=mlp)
            self.reuse_feature[i] = reuse_feature

        x = self.final_layer(x, c)
        x = self.unpatchify(x)

        self.cur_timestep -= 1
        return x
